trigger ContactIndustry on Contact (before insert, before update) {
  Set<Id> accIds = new Set<Id>();
  for (Contact c : Trigger.new) accIds.add(c.AccountId);
  Map<Id, Account> accs = new Map<Id, Account>(
    [SELECT Industry FROM Account WHERE Id IN :accIds]);
  for (Contact c : Trigger.new) {
    if (accs.containsKey(c.AccountId)) {
      c.Industry__c = accs.get(c.AccountId).Industry;
    }
  }
}

